/*
  pingoscope — RECEIVER (CYD ESP32-32E / ST7789)
    L1 (size 2): [CC tag] egress-IP + countdown pie (tag white, RED on country change)
    L2 (size 1): city, country     L3 (size 1): ASN
    L4: fixed-slot newest-left ticker (no scroll)
    rest: cardio graph on blue field, margin Y-labels
  BOOT = debug. Display library files live in this folder. Board: ESP32 Dev Module.
*/
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <WiFi.h>
#include <esp_now.h>
#include <esp_wifi.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>

#define TFT_CS 15
#define TFT_DC 2
#define TFT_RST -1
#define TFT_BL 21
Adafruit_ST7789 tft(TFT_CS, TFT_DC, TFT_RST);

#define LED_R 22
#define LED_G 16
#define LED_B 17
inline void ledOff(){ digitalWrite(LED_R,HIGH); digitalWrite(LED_G,HIGH); digitalWrite(LED_B,HIGH); }
inline void ledGreen(bool on){ digitalWrite(LED_G,on?LOW:HIGH); }
inline void ledRed(bool on){ digitalWrite(LED_R,on?LOW:HIGH); }

#define BTN 0
#define ESPNOW_CHANNEL 1
#define MSG_PROBE 1
#define MSG_NETINFO 2
#define RTT_CAP 300
#define NETINFO_PERIOD_MS 5000

typedef struct __attribute__((packed)) { uint8_t type; uint32_t seq; uint16_t rtt_ms; uint8_t status; } probe_t;
typedef struct __attribute__((packed)) { uint8_t type; char ip[16]; char cc[4]; char city[24]; char country[32]; char asn[40]; } netinfo_t;

const char* statusLabel(uint8_t s){ switch(s){case 0:return "OK";case 1:return "PING TIMEOUT";case 2:return "NO IP";default:return "LINK DOWN";} }

#define COL_BG        0x0000
#define COL_IP        0xFFFF
#define COL_GEO       0x07FF
#define COL_ASN       0x9CF3
#define COL_TICK_BG   0x2124
#define COL_TICK_HIST 0xAD55
#define COL_TICK_CUR  0xFFFF
#define COL_PLOT_BG   0x0014
#define COL_TRACE     0x07E0
#define COL_FAIL      0xF800
#define COL_AXIS      0x8410
#define COL_YLABEL    0xFFFF
#define COL_FRESH     0x07FF

#define PIE_R   9
#define FRESH_X 298
#define FRESH_Y 0
#define IP_Y    2
#define GEO_Y   22
#define ASN_Y   32
#define TICK_Y  44
#define TICK_H  16
#define LBL_TOP_Y 62
#define PLOT_X0 2
#define PLOT_W  316
#define PLOT_Y0 74
#define PLOT_Y1 226
#define PLOT_H  (PLOT_Y1 - PLOT_Y0)
#define LBL_BOT_Y 228
#define HIST    PLOT_W
#define SLOT_W  48

uint16_t colRtt[HIST]; uint8_t colSt[HIST];
uint16_t sRtt[HIST];   uint8_t sSt[HIST];
int sHead=0, sCount=0;
int sweepX=0;
int yFloor=0, yCeil=40;
int gPrevX=-1, gPrevY=-1; bool gPrevValid=false;

volatile bool newProbe=false, newNet=false;
probe_t  lastProbe = {MSG_PROBE,0,0,2};
netinfo_t lastNet;
char curIp[16]="", curCc[4]="", curCity[24]="", curCountry[32]="", curAsn[40]="", baseCc[4]="";

uint8_t lastMac[6];
int lastRssi=0;
uint32_t pktCount=0, missed=0, prevSeq=0;
bool haveSeq=false;
unsigned long lastRxMs=0, lastNetMs=0, lastIntervalMs=0, lastFrame=0;

bool debugMode=false, forceRedraw=false;
unsigned long ledOffAt=0;

GFXcanvas16 tcanvas(320, TICK_H);
GFXcanvas16 pcanvas(2*PIE_R+2, 2*PIE_R+2);

void handleRx(const uint8_t *mac, const uint8_t *data, int len){
  if (len<1) return;
  memcpy((void*)lastMac, mac, 6);
  unsigned long now=millis();
  if (data[0]==MSG_PROBE && len==(int)sizeof(probe_t)){
    memcpy(&lastProbe, data, sizeof(probe_t));
    lastIntervalMs = now-lastRxMs; pktCount++;
    if (haveSeq && lastProbe.seq>prevSeq+1) missed += (lastProbe.seq-prevSeq-1);
    prevSeq=lastProbe.seq; haveSeq=true; newProbe=true;
  } else if (data[0]==MSG_NETINFO && len==(int)sizeof(netinfo_t)){
    memcpy(&lastNet, data, sizeof(netinfo_t)); newNet=true;
  }
  lastRxMs=now;
}
#if ESP_ARDUINO_VERSION >= ESP_ARDUINO_VERSION_VAL(3,0,0)
void onRecv(const esp_now_recv_info_t *info, const uint8_t *data, int len){ lastRssi=info->rx_ctrl->rssi; handleRx(info->src_addr,data,len); }
#else
void onRecv(const uint8_t *mac, const uint8_t *data, int len){ lastRssi=0; handleRx(mac,data,len); }
#endif

String macStr(const uint8_t*m){ char b[18]; sprintf(b,"%02X:%02X:%02X:%02X:%02X:%02X",m[0],m[1],m[2],m[3],m[4],m[5]); return String(b); }

static int cmp_u16(const void*a,const void*b){ return (int)(*(const uint16_t*)a)-(int)(*(const uint16_t*)b); }
void computeScale(int &nf,int &nc){
  static uint16_t tmp[HIST];
  int n=0; uint16_t mn=65535;
  for (int i=0;i<sCount;i++){ if (sSt[i]==0){ tmp[n++]=sRtt[i]; if(sRtt[i]<mn)mn=sRtt[i]; } }
  if (n==0){ nf=0; nc=40; return; }
  qsort(tmp,n,sizeof(uint16_t),cmp_u16);
  int p = tmp[(int)(n*0.95)];
  int ceil=(int)(p*1.15)+2;
  int step = ceil<=50?5 : ceil<=100?10 : ceil<=200?20 : 25;
  ceil=((ceil+step-1)/step)*step; if (ceil>RTT_CAP) ceil=RTT_CAP;
  int floor=(mn/step)*step; if (floor<0) floor=0;
  if (ceil-floor<step) ceil=floor+step;
  nf=floor; nc=ceil;
}
int mapY(uint16_t rtt){
  int v=rtt; if(v>yCeil)v=yCeil; if(v<yFloor)v=yFloor;
  long span=yCeil-yFloor; if(span<1)span=1;
  int y=PLOT_Y1-(int)((long)(v-yFloor)*(PLOT_H-1)/span);
  if(y<PLOT_Y0)y=PLOT_Y0; if(y>PLOT_Y1)y=PLOT_Y1;
  return y;
}

void drawYLabels(){
  tft.fillRect(0,LBL_TOP_Y,120,10,COL_BG);
  tft.fillRect(0,LBL_BOT_Y,120,10,COL_BG);
  tft.setTextSize(1); tft.setTextColor(COL_YLABEL,COL_BG);
  char b[12];
  sprintf(b,"%dms",yCeil);  tft.setCursor(2,LBL_TOP_Y+1); tft.print(b);
  sprintf(b,"%dms",yFloor); tft.setCursor(2,LBL_BOT_Y+1); tft.print(b);
}

void drawColumn(int col){
  int x=PLOT_X0+col;
  if (colSt[col]!=0){ tft.drawFastVLine(x,PLOT_Y0,PLOT_H,COL_FAIL); gPrevValid=false; }
  else { int y=mapY(colRtt[col]);
    if (gPrevValid && gPrevX==x-1) tft.drawLine(gPrevX,gPrevY,x,y,COL_TRACE); else tft.drawPixel(x,y,COL_TRACE);
    gPrevX=x; gPrevY=y; gPrevValid=true; }
}

void fullGraphRedraw(int uptoCol){
  tft.fillRect(PLOT_X0,PLOT_Y0,PLOT_W,PLOT_H,COL_PLOT_BG);
  int lpx=-1,lpy=-1; bool lpv=false;
  for (int c=0;c<=uptoCol;c++){
    int x=PLOT_X0+c;
    if (colSt[c]!=0){ tft.drawFastVLine(x,PLOT_Y0,PLOT_H,COL_FAIL); lpv=false; }
    else { int y=mapY(colRtt[c]);
      if (lpv && lpx==x-1) tft.drawLine(lpx,lpy,x,y,COL_TRACE); else tft.drawPixel(x,y,COL_TRACE);
      lpx=x; lpy=y; lpv=true; }
  }
  drawYLabels();
  gPrevX=lpx; gPrevY=lpy; gPrevValid=lpv;
}

void onSample(uint16_t rtt,uint8_t st){
  sRtt[sHead]=rtt; sSt[sHead]=st; sHead=(sHead+1)%HIST; if(sCount<HIST)sCount++;
  int col=sweepX; colRtt[col]=rtt; colSt[col]=st;
  int nf,nc; computeScale(nf,nc);
  bool rescaled=(nf!=yFloor||nc!=yCeil);
  if (rescaled){ yFloor=nf; yCeil=nc; fullGraphRedraw(col); } else drawColumn(col);
  sweepX++;
  if (sweepX>=HIST){ sweepX=0; tft.fillRect(PLOT_X0,PLOT_Y0,PLOT_W,PLOT_H,COL_PLOT_BG); gPrevValid=false; }
}

void drawTicker(){
  tcanvas.fillScreen(COL_TICK_BG);
  tcanvas.setTextSize(2);
  int shown = sCount<7?sCount:7;
  for (int k=0;k<shown;k++){
    int idx=(sHead-1-k+HIST*2)%HIST;
    int x=4 + k*SLOT_W;
    if (x>316) break;
    char buf[8]; if (sSt[idx]==0) sprintf(buf,"%u",sRtt[idx]); else strcpy(buf,"x");
    tcanvas.setTextColor(k==0?COL_TICK_CUR:COL_TICK_HIST);
    tcanvas.setCursor(x,0); tcanvas.print(buf);
  }
  tft.drawRGBBitmap(0,TICK_Y,tcanvas.getBuffer(),320,TICK_H);
}

void drawFreshnessPie(){
  unsigned long age = lastNetMs ? (millis()-lastNetMs) : NETINFO_PERIOD_MS;
  float frac = 1.0f - (float)age/NETINFO_PERIOD_MS; if(frac<0)frac=0; if(frac>1)frac=1;
  bool stale = lastNetMs && age > (unsigned long)NETINFO_PERIOD_MS*2;
  int R=PIE_R, cx=R, cy=R;
  pcanvas.fillScreen(COL_BG);
  if (!stale){
    int start=(int)((1.0f-frac)*360);
    for (int d=start; d<360; d++){
      float a=(d-90)*0.0174533f;
      int x2=cx+(int)(R*cosf(a)), y2=cy+(int)(R*sinf(a));
      pcanvas.drawLine(cx,cy,x2,y2,COL_FRESH);
    }
  }
  pcanvas.drawCircle(cx,cy,R, stale?COL_FAIL:COL_AXIS);
  tft.drawRGBBitmap(FRESH_X,FRESH_Y,pcanvas.getBuffer(),2*R+2,2*R+2);
}

void drawL1(){
  tft.fillRect(0,IP_Y,FRESH_X-2,20,COL_BG);
  const char* cc = curCc[0]?curCc:"??";
  int tagW = (int)strlen(cc)*12 + 8;
  bool changed = (baseCc[0] && strcmp(baseCc,curCc)!=0);
  uint16_t tagBg = changed?COL_FAIL:COL_IP;
  uint16_t tagFg = changed?COL_IP:COL_BG;
  tft.fillRoundRect(2, IP_Y, tagW, 18, 3, tagBg);
  tft.setTextSize(2); tft.setTextColor(tagFg);
  tft.setCursor(6, IP_Y+2); tft.print(cc);
  tft.setTextColor(COL_IP, COL_BG);
  tft.setCursor(2+tagW+6, IP_Y+2); tft.print(curIp[0]?curIp:"(no ip)");
}
void drawL2(){
  tft.fillRect(0,GEO_Y,320,9,COL_BG);
  tft.setTextSize(1); tft.setTextColor(COL_GEO,COL_BG);
  char line[64];
  if (curCity[0] && curCountry[0]) snprintf(line,sizeof(line),"%s, %s", curCity, curCountry);
  else if (curCountry[0]) { strncpy(line,curCountry,sizeof(line)-1); line[sizeof(line)-1]=0; }
  else if (curCity[0])    { strncpy(line,curCity,sizeof(line)-1); line[sizeof(line)-1]=0; }
  else line[0]=0;
  const int MAXCH=52; if ((int)strlen(line)>MAXCH){ line[MAXCH]=0; char*sp=strrchr(line,' '); if(sp)*sp=0; }
  tft.setCursor(2,GEO_Y); tft.print(line[0]?line:" ");
}
void drawL3(){
  tft.fillRect(0,ASN_Y,320,9,COL_BG);
  tft.setTextSize(1); tft.setTextColor(COL_ASN,COL_BG);
  char line[48]; strncpy(line,curAsn,sizeof(line)-1); line[sizeof(line)-1]=0;
  const int MAXCH=52; if ((int)strlen(line)>MAXCH){ line[MAXCH]=0; char*sp=strrchr(line,' '); if(sp)*sp=0; }
  tft.setCursor(2,ASN_Y); tft.print(line[0]?line:" ");
}

void applyNet(){
  strncpy(curIp,lastNet.ip,sizeof(curIp)-1); curIp[sizeof(curIp)-1]=0;
  strncpy(curCc,lastNet.cc,sizeof(curCc)-1); curCc[sizeof(curCc)-1]=0;
  strncpy(curCity,lastNet.city,sizeof(curCity)-1); curCity[sizeof(curCity)-1]=0;
  strncpy(curCountry,lastNet.country,sizeof(curCountry)-1); curCountry[sizeof(curCountry)-1]=0;
  strncpy(curAsn,lastNet.asn,sizeof(curAsn)-1); curAsn[sizeof(curAsn)-1]=0;
  if (baseCc[0]==0 && curCc[0]) strncpy(baseCc,curCc,sizeof(baseCc));
}

void drawChrome(){
  tft.fillScreen(COL_BG);
  tft.fillRect(PLOT_X0,PLOT_Y0,PLOT_W,PLOT_H,COL_PLOT_BG);
  drawL1(); drawL2(); drawL3(); drawYLabels();
}

void drawDebug(){
  tft.fillScreen(COL_BG);
  tft.setTextColor(0xFFE0); tft.setTextSize(2); tft.setCursor(6,6); tft.println("DEBUG / raw ESP-NOW");
  tft.setTextColor(COL_IP); tft.setTextSize(1); int y=34;
  tft.setCursor(6,y); tft.print("from  "); tft.println(macStr(lastMac)); y+=12;
  tft.setCursor(6,y); tft.print("rssi  "); tft.print(lastRssi); tft.println(" dBm"); y+=12;
  tft.setCursor(6,y); tft.print("pkts  "); tft.print(pktCount); tft.print("  missed "); tft.println(missed); y+=12;
  tft.setCursor(6,y); tft.print("rate  "); tft.print(lastIntervalMs?1000.0/lastIntervalMs:0,2); tft.println(" /s"); y+=16;
  tft.setCursor(6,y); tft.print("PROBE seq "); tft.print(lastProbe.seq);
    tft.print(" rtt "); tft.print(lastProbe.rtt_ms); tft.print(" st "); tft.print(lastProbe.status); tft.println(); y+=12;
  tft.setCursor(6,y); tft.print("scale "); tft.print(yFloor); tft.print(".."); tft.print(yCeil); tft.println(" ms"); y+=16;
  tft.setCursor(6,y); tft.print("ip "); tft.print(curIp[0]?curIp:"-"); tft.print("  cc "); tft.print(curCc); tft.print(" base "); tft.println(baseCc[0]?baseCc:"-"); y+=12;
  tft.setCursor(6,y); tft.print("loc "); tft.print(curCity); tft.print(", "); tft.println(curCountry); y+=12;
  tft.setCursor(6,y); tft.print("as  "); tft.println(curAsn[0]?curAsn:"-");
}

void setup(){
  Serial.begin(115200); delay(300);
  pinMode(LED_R,OUTPUT); pinMode(LED_G,OUTPUT); pinMode(LED_B,OUTPUT); ledOff();
  pinMode(BTN,INPUT_PULLUP);
  pinMode(TFT_BL,OUTPUT); digitalWrite(TFT_BL,HIGH);
  SPI.begin(14,12,13,15);
  tft.init(240,320); tft.setRotation(1);
  uint8_t madctl=ST77XX_MADCTL_MX|ST77XX_MADCTL_MY|ST77XX_MADCTL_MV | 0x08; // 0x08=BGR
  tft.sendCommand(ST77XX_MADCTL,&madctl,1);
  tft.invertDisplay(false);

  drawChrome();
  tft.setTextSize(1); tft.setTextColor(COL_AXIS,COL_PLOT_BG);
  tft.setCursor(PLOT_X0+6,PLOT_Y0+PLOT_H/2-4); tft.print("waiting for packets...");

  WiFi.mode(WIFI_STA); WiFi.disconnect();
  esp_wifi_set_channel(ESPNOW_CHANNEL,WIFI_SECOND_CHAN_NONE);
  Serial.print("RX MAC: "); Serial.println(WiFi.macAddress());
  if (esp_now_init()!=ESP_OK){ tft.fillScreen(COL_FAIL); return; }
  esp_now_register_recv_cb(onRecv);
}

void loop(){
  static unsigned long lastToggle=0;
  if (digitalRead(BTN)==LOW && millis()-lastToggle>250){ lastToggle=millis(); debugMode=!debugMode; forceRedraw=true; }

  if (forceRedraw){ forceRedraw=false;
    if (debugMode) drawDebug();
    else { drawChrome(); if (sweepX>0) fullGraphRedraw(sweepX-1); drawTicker(); }
  }

  if (newProbe){ newProbe=false;
    if (!debugMode){ onSample(lastProbe.rtt_ms,lastProbe.status); drawTicker(); }
    ledGreen(true); ledOffAt=millis()+80;
  }
  if (newNet){ newNet=false; applyNet(); lastNetMs=millis(); if(!debugMode){ drawL1(); drawL2(); drawL3(); } }

  if (!debugMode && millis()-lastFrame>=40){ lastFrame=millis(); drawFreshnessPie(); }

  if (ledOffAt && millis()>ledOffAt){ ledGreen(false); ledOffAt=0; }
  ledRed(lastRxMs && millis()-lastRxMs>5000);
}

